<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import { adminApi } from '@/api';
import ConfirmDialog from '@/components/common/ConfirmDialog.vue';
import { useToast } from '@/stores/toast';
import { buildStockCountPayload, paginateWarehouseItems, stockCountProgress, stockCountSummary, stockCountVariance, validateStockCount } from '@/utils/inventoryOperations';
import { formatQuantity } from '@/utils/inventoryItem';

const toast = useToast();
const counts = ref([]);
const inventoryItems = ref([]);
const selected = ref(null);
const loading = ref(true);
const error = ref('');
const saving = ref(false);
const filter = ref('ALL');
const approvalOpen = ref(false);
const createForm = ref({ countDate: new Date().toLocaleDateString('en-CA'), inventoryItemIds: [] });
const PAGE_SIZE = 10;
const ingredientPage = ref(1);
const ingredientSearch = ref('');
const ingredientFilter = ref('ACTIVE');
const showAllCounts = ref(false);
const selectableIngredients = computed(() => inventoryItems.value.filter((item) => item.active !== false && item.itemType === 'INGREDIENT'));
const filteredSelectableIngredients = computed(() => selectableIngredients.value.filter(item => {
  const query = ingredientSearch.value.trim().toLocaleLowerCase('vi');
  if (query && !`${item.name} ${item.inventoryCode}`.toLocaleLowerCase('vi').includes(query)) return false;
  return ingredientFilter.value === 'ALL' || item.active !== false;
}));
const paginatedSelectableIngredients = computed(() => paginateWarehouseItems(filteredSelectableIngredients.value, ingredientPage.value, PAGE_SIZE));
const visibleCounts = computed(() => showAllCounts.value ? counts.value : counts.value.slice(0, 5));
const itemById = computed(() => new Map(inventoryItems.value.map((item) => [item.inventoryItemId, item])));
const itemsObject = computed(() => Object.fromEntries(inventoryItems.value.map((item) => [item.inventoryItemId, item])));
const progress = computed(() => stockCountProgress(selected.value?.items));
const summary = computed(() => stockCountSummary(selected.value?.items, itemsObject.value));
const varianceCount = computed(() => (selected.value?.items || []).filter(line => stockCountVariance(line).quantity !== null && stockCountVariance(line).quantity !== 0).length);
const matchedCount = computed(() => (selected.value?.items || []).filter(line => stockCountVariance(line).quantity === 0).length);
const reservedShortageLines = computed(() => (selected.value?.items || []).filter(line => line.actualQuantity !== '' && line.actualQuantity != null && Number(line.actualQuantity) < Number(line.reservedQuantitySnapshot || 0)));
const filteredLines = computed(() => (selected.value?.items || []).filter((line) => {
  if (filter.value === 'UNCOUNTED') return line.actualQuantity === '' || line.actualQuantity == null;
  if (filter.value === 'VARIANCE') return stockCountVariance(line).quantity !== null && stockCountVariance(line).quantity !== 0;
  if (filter.value === 'MATCHED') return stockCountVariance(line).quantity === 0;
  return true;
}));
function item(id) { return itemById.value.get(Number(id)) || {}; }
function toggleIngredient(id) { const selected = new Set(createForm.value.inventoryItemIds); selected.has(id) ? selected.delete(id) : selected.add(id); createForm.value.inventoryItemIds = [...selected]; }
function selectAllFiltered() { createForm.value.inventoryItemIds = [...new Set([...createForm.value.inventoryItemIds, ...filteredSelectableIngredients.value.map(item => item.inventoryItemId)])]; }
function clearFiltered() { const filteredIds = new Set(filteredSelectableIngredients.value.map(item => item.inventoryItemId)); createForm.value.inventoryItemIds = createForm.value.inventoryItemIds.filter(id => !filteredIds.has(id)); }
function money(value) { return Number(value).toLocaleString('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }); }
function variance(line) { return stockCountVariance(line, item(line.inventoryItemId).averageUnitCost); }
function hasVariance(line) { return variance(line).quantity !== null && variance(line).quantity !== 0; }
async function load() { loading.value = true; error.value = ''; try { const [list, items] = await Promise.all([adminApi.getStockCounts(), adminApi.getInventoryItems()]); counts.value = Array.isArray(list) ? list : []; inventoryItems.value = Array.isArray(items) ? items : []; const validIds = new Set(selectableIngredients.value.map((item) => item.inventoryItemId)); createForm.value.inventoryItemIds = createForm.value.inventoryItemIds.filter((id) => validIds.has(id)); if (!createForm.value.inventoryItemIds.length) createForm.value.inventoryItemIds = [...validIds]; } catch (e) { error.value = e.message || 'Không thể tải phiếu kiểm kê'; } finally { loading.value = false; } }
async function create() { if (!createForm.value.inventoryItemIds.length) { error.value = 'Chọn ít nhất một nguyên liệu để kiểm kê'; return; } saving.value = true; error.value = ''; try { const data = await adminApi.createStockCount(createForm.value); toast.success('Đã tạo phiếu kiểm kê'); await load(); await open(data); } catch (e) { error.value = e.message || 'Không thể tạo phiếu kiểm kê'; } finally { saving.value = false; } }
async function open(count) { error.value = ''; filter.value = 'ALL'; try { const data = await adminApi.getStockCount(count.stockCountId); selected.value = { ...data, items: data.items.map((line) => ({ ...line, actualQuantity: line.actualQuantity == null ? '' : String(line.actualQuantity), reasonCode: line.reasonCode || '', note: line.note || '' })) }; } catch (e) { error.value = e.message || 'Không thể mở phiếu kiểm kê'; } }
async function save() { const validation = validateStockCount(selected.value.items); if (validation.items) { error.value = validation.items; return false; } saving.value = true; error.value = ''; try { selected.value = await adminApi.updateStockCount(selected.value.stockCountId, buildStockCountPayload(selected.value.items)); toast.success('Đã lưu số kiểm thực tế'); await load(); return true; } catch (e) { error.value = e.message || 'Xung đột dữ liệu kiểm kê. Mở lại phiếu và kiểm tra số lý thuyết.'; return false; } finally { saving.value = false; } }
async function approve() { if (!(await save())) { approvalOpen.value = false; return; } saving.value = true; try { selected.value = await adminApi.approveStockCount(selected.value.stockCountId); toast.success('Đã duyệt kiểm kê'); await load(); } catch (e) { error.value = e.message || 'Không thể duyệt kiểm kê'; } finally { saving.value = false; approvalOpen.value = false; } }
function requestApproval() { const validation = validateStockCount(selected.value.items); if (validation.items) { error.value = validation.items; return; } error.value = ''; approvalOpen.value = true; }
watch([ingredientSearch, ingredientFilter], () => { ingredientPage.value = 1; });
watch(() => paginatedSelectableIngredients.value.page, page => { if (ingredientPage.value !== page) ingredientPage.value = page; });
onMounted(load);
</script>

<template>
  <main class="count-page">
    <header class="page-heading"><div><p class="eyebrow">Kho · Đối chiếu thực tế</p><h1>Kiểm kê kho</h1><p>Ghi nhận số đếm, nhận diện chênh lệch và cập nhật tồn kho có kiểm soát.</p></div><button class="btn btn-outline" :disabled="loading" @click="load">Làm mới</button></header>
    <section v-if="selected" class="command-rail count-command-rail" aria-label="Tiến độ kiểm kê"><article class="command-card"><span>Tiến độ</span><strong>{{ progress.counted }}/{{ progress.total }}</strong><small>{{ progress.percent }}% đã ghi nhận</small></article><article class="command-card"><span>Đã khớp</span><strong>{{ matchedCount }}</strong><small>Không cần điều chỉnh</small></article><article class="command-card attention"><span>Có chênh lệch</span><strong>{{ varianceCount }}</strong><small>Thiếu {{ summary.shortageItemCount }} · dư {{ summary.surplusItemCount }}</small></article><article class="command-card" :class="{ urgent: reservedShortageLines.length }"><span>Rủi ro lượng đã giữ</span><strong>{{ reservedShortageLines.length }}</strong><small>Thực tế thấp hơn ảnh chụp đã giữ</small></article></section>
    <ol class="stages" aria-label="Ba bước kiểm kê"><li class="active"><span>1</span><strong>Chọn nhóm</strong></li><li :class="{ active: selected }"><span>2</span><strong>Nhập số đếm</strong></li><li :class="{ active: progress.percent === 100 }"><span>3</span><strong>Xem chênh lệch & duyệt</strong></li></ol>
    <fieldset class="panel create-panel selection-workspace"><legend>1. Chọn nguyên liệu cần kiểm</legend><form @submit.prevent="create"><header class="selection-heading"><div><h2>Chọn nguyên liệu kiểm kê</h2><p>{{ createForm.inventoryItemIds.length }} nguyên liệu đã chọn</p></div></header><div class="selection-toolbar"><label><span class="sr-only">Tìm nguyên liệu</span><input v-model="ingredientSearch" class="form-input" type="search" placeholder="Tìm nguyên liệu..." /></label><label><span class="sr-only">Lọc nguyên liệu</span><select v-model="ingredientFilter" class="form-select"><option value="ACTIVE">Đang sử dụng</option><option value="ALL">Tất cả</option></select></label><button type="button" class="btn btn-outline" @click="selectAllFiltered">Chọn tất cả</button><button type="button" class="btn btn-ghost" @click="clearFiltered">Bỏ chọn</button></div><div v-if="selectableIngredients.length" class="ingredient-selection-grid"><label v-for="ingredient in paginatedSelectableIngredients.items" :key="ingredient.inventoryItemId" class="ingredient-option-card" :class="{ selected: createForm.inventoryItemIds.includes(ingredient.inventoryItemId) }"><input :checked="createForm.inventoryItemIds.includes(ingredient.inventoryItemId)" type="checkbox" @change="toggleIngredient(ingredient.inventoryItemId)" /><span><strong>{{ ingredient.name }}</strong><small>{{ ingredient.inventoryCode }}</small><small>Hệ thống: {{ formatQuantity(ingredient.onHandQuantity) }} {{ item(ingredient.inventoryItemId).baseUnit }}</small></span><i aria-hidden="true">✓</i></label></div><div v-else class="state">Chưa có nguyên liệu đang hoạt động. Hãy thêm nguyên liệu trước khi tạo phiếu kiểm kê.</div><footer class="selection-footer"><div class="selection-pagination"><span>{{ paginatedSelectableIngredients.from }}–{{ paginatedSelectableIngredients.to }} / {{ paginatedSelectableIngredients.totalItems }} nguyên liệu</span><nav aria-label="Phân trang chọn nguyên liệu"><button type="button" :disabled="paginatedSelectableIngredients.page === 1" @click="ingredientPage--">‹</button><button v-for="page in paginatedSelectableIngredients.totalPages" :key="page" type="button" :class="{ active: page === paginatedSelectableIngredients.page }" :aria-current="page === paginatedSelectableIngredients.page ? 'page' : undefined" @click="ingredientPage = page">{{ page }}</button><button type="button" :disabled="paginatedSelectableIngredients.page === paginatedSelectableIngredients.totalPages" @click="ingredientPage++">›</button></nav></div><div class="create-row"><label>Ngày kiểm<input v-model="createForm.countDate" class="form-input" type="date" required /></label><strong>{{ createForm.inventoryItemIds.length }} nguyên liệu đã chọn</strong><button class="btn btn-primary" :disabled="saving || !createForm.inventoryItemIds.length">Tạo phiếu kiểm kê</button></div></footer></form></fieldset>
    <p v-if="error" class="error-box" role="alert">{{ error }}</p>
    <section class="workspace variance-review-workspace"><div class="panel list-panel recent-count-rail"><h2>Phiếu kiểm kê</h2><div v-if="loading" class="state" role="status">Đang tải...</div><div v-else-if="!counts.length" class="state">Chưa có phiếu kiểm kê.</div><button v-for="count in visibleCounts" :key="count.stockCountId" class="count-row" :class="{active:selected?.stockCountId===count.stockCountId}" @click="open(count)"><span><strong>#{{ count.stockCountId }} · {{ count.countDate }}</strong><small>{{ count.frequency === 'DAILY' ? 'Hàng ngày' : 'Hàng tuần' }} · {{ count.items.length }} mặt hàng</small></span><span class="badge" :class="count.status==='DRAFT'?'badge-warning':'badge-success'">{{ count.status==='DRAFT'?'Nháp':'Đã duyệt' }}</span></button><button v-if="counts.length > 5" type="button" class="btn btn-ghost all-counts" @click="showAllCounts = !showAllCounts">{{ showAllCounts ? 'Thu gọn' : 'Xem tất cả phiếu' }}</button></div>
      <section class="panel editor"><div v-if="!selected" class="state">Chọn một phiếu để bắt đầu đếm.</div><template v-else><div class="editor-heading"><div><h2>2. Nhập số đếm · Phiếu #{{ selected.stockCountId }}</h2><p>{{ selected.countDate }} · {{ selected.frequency }}</p></div><span class="badge" :class="selected.status==='DRAFT'?'badge-warning':'badge-success'">{{ selected.status==='DRAFT'?'Đang đếm':'Đã duyệt' }}</span></div>
        <div class="progress-block" aria-live="polite"><div><strong>Đã đếm {{ progress.counted }}/{{ progress.total }}</strong><span>{{ progress.percent }}%</span></div><progress :value="progress.counted" :max="progress.total || 1">{{ progress.percent }}%</progress></div>
        <div class="filters" role="group" aria-label="Lọc kết quả đếm"><button type="button" :aria-pressed="filter==='ALL'" @click="filter='ALL'">Tất cả</button><button type="button" :aria-pressed="filter==='UNCOUNTED'" @click="filter='UNCOUNTED'">Chưa đếm</button><button type="button" :aria-pressed="filter==='VARIANCE'" @click="filter='VARIANCE'">Có chênh lệch</button><button type="button" :aria-pressed="filter==='MATCHED'" @click="filter='MATCHED'">Đã khớp</button></div>
        <div v-if="reservedShortageLines.length" class="reserved-shortage-warning" role="status"><strong>{{ reservedShortageLines.length }} nguyên liệu thấp hơn lượng đã giữ.</strong><span>Vẫn có thể duyệt để phản ánh tồn thực tế; lượng khả dụng mới sẽ bằng 0.</span></div><div v-if="!selected.items.length" class="state">Không có mặt hàng theo lịch này.</div><form v-else @submit.prevent="save"><div class="table-wrapper count-card-list"><table class="table"><thead><tr><th>Mặt hàng</th><th>Tồn hệ thống</th><th>Đã giữ</th><th>Số đếm được</th><th>Chênh lệch</th><th>Lý do</th><th>Ghi chú</th></tr></thead><tbody><tr v-for="line in filteredLines" :key="line.inventoryItemId"><td data-label="Mặt hàng"><strong>{{ item(line.inventoryItemId).inventoryCode || `#${line.inventoryItemId}` }}</strong><small>{{ item(line.inventoryItemId).name }}</small></td><td data-label="Tồn hệ thống">{{ formatQuantity(line.theoreticalQuantity) }}</td><td data-label="Đã giữ">{{ formatQuantity(line.reservedQuantitySnapshot) }}</td><td data-label="Số đếm được"><input v-model="line.actualQuantity" class="form-input compact" type="number" min="0" step="0.0001" required :disabled="selected.status!=='DRAFT'" :aria-label="`Số đếm được của ${item(line.inventoryItemId).name}`" /></td><td data-label="Chênh lệch"><template v-if="variance(line).quantity !== null"><strong :class="variance(line).quantity<0?'negative':variance(line).quantity>0?'positive':''">{{ formatQuantity(variance(line).quantity) }}</strong><small>{{ money(Math.abs(variance(line).cost)) }}</small></template><span v-else class="muted">Chưa đếm</span></td><td data-label="Lý do"><input v-if="hasVariance(line)" v-model="line.reasonCode" class="form-input compact" maxlength="50" required :disabled="selected.status!=='DRAFT'" :aria-label="`Lý do chênh lệch của ${item(line.inventoryItemId).name}`" /><small v-if="hasVariance(line)">Bắt buộc khi có chênh lệch</small><span v-else class="muted">Không cần</span></td><td data-label="Ghi chú"><input v-model="line.note" class="form-input compact" maxlength="500" :disabled="selected.status!=='DRAFT'" :aria-label="`Ghi chú kiểm kê của ${item(line.inventoryItemId).name}`" /></td></tr></tbody></table></div>
          <section class="summary variance-summary" aria-labelledby="count-summary"><h3 id="count-summary">3. Xem chênh lệch & duyệt</h3><dl><div><dt>Mặt hàng thiếu</dt><dd>{{ summary.shortageItemCount }}</dd></div><div><dt>Mặt hàng dư</dt><dd>{{ summary.surplusItemCount }}</dd></div><div><dt>Giá trị hao hụt</dt><dd>{{ money(summary.lossCost) }}</dd></div></dl></section>
          <div v-if="selected.status==='DRAFT'" class="actions"><button class="btn btn-outline" :disabled="saving">Lưu nháp</button><button type="button" class="btn btn-primary" :disabled="saving" @click="requestApproval">Kiểm tra và duyệt</button></div><p v-else class="locked"><i class="bi bi-lock" aria-hidden="true"></i> Phiếu đã duyệt và khóa chỉnh sửa.</p>
        </form></template></section></section>
    <ConfirmDialog :open="approvalOpen" :busy="saving" :title="`Duyệt phiếu kiểm kê #${selected?.stockCountId}?`" :message="`Tồn kho sẽ đổi theo số đếm thực tế. Có ${summary.shortageItemCount} mặt hàng thiếu, ${summary.surplusItemCount} mặt hàng dư, giá trị hao hụt ${money(summary.lossCost)}.`" confirm-label="Duyệt và cập nhật kho" @confirm="approve" @cancel="approvalOpen=false" />
  </main>
</template>

<style scoped>
.count-page{display:grid;gap:20px}.command-rail{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.command-card{display:grid;gap:6px;min-height:104px;padding:16px;border:1px solid var(--admin-border);border-radius:var(--admin-panel-radius);background:#fff}.command-card>span{color:var(--admin-muted);font-size:10px;font-weight:800;letter-spacing:.06em;text-transform:uppercase}.command-card strong{font-size:24px}.command-card small{color:var(--admin-muted)}.command-card.attention{background:var(--admin-warning-soft)}.command-card.urgent{border-color:var(--admin-danger);background:var(--admin-danger-soft);color:var(--admin-danger)}.reserved-shortage-warning{display:flex;gap:10px;margin-bottom:12px;padding:12px;border-radius:10px;background:var(--admin-danger-soft);color:var(--admin-danger)}.panel,.command-card{box-shadow:0 10px 28px rgba(15,23,42,.06)}.selection-workspace{padding:22px}.selection-workspace form{display:grid!important;gap:16px;align-items:stretch!important}.selection-heading{display:flex;justify-content:space-between}.selection-heading h2{margin:0 0 4px}.selection-heading p{margin:0;color:var(--admin-muted)}.selection-toolbar{display:grid;grid-template-columns:minmax(220px,1fr) 180px auto auto;gap:8px}.ingredient-selection-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.ingredient-option-card{position:relative;display:flex!important;align-items:center;gap:12px;min-height:76px;padding:14px;border:1px solid var(--admin-border);border-radius:14px;background:#fff;cursor:pointer}.ingredient-option-card.selected{border-color:var(--admin-brand);background:var(--admin-brand-soft)}.ingredient-option-card input{position:absolute;width:1px;height:1px;opacity:0}.ingredient-option-card span{display:grid;gap:3px}.ingredient-option-card small{color:var(--admin-muted)}.ingredient-option-card i{display:grid;place-items:center;width:24px;height:24px;margin-left:auto;border-radius:50%;background:var(--admin-border);color:transpare