rid;grid-template-columns:minmax(260px,1fr) minmax(0,3fr);gap:18px;align-items:start}.list-panel{display:grid;gap:8px}.count-row{display:flex;justify-content:space-between;align-items:center;gap:8px;min-height:54px;text-align:left;padding:12px;border:1px solid var(--border-light);border-radius:9px;background:#fff}.count-row:hover,.count-row.active{border-color:var(--primary);background:var(--primary-50)}.count-row small,.table small{display:block;color:var(--text-mid);margin-top:3px}.state{text-align:center;padding:32px;color:var(--text-mid)}.error-box{margin:0;color:#b91c1c;background:#fef2f2;padding:10px;border-radius:8px}.progress-block{display:grid;gap:6px;margin-bottom:12px}.progress-block div{display:flex;justify-content:space-between}.progress-block progress{width:100%;height:10px;accent-color:var(--primary)}.filters{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px}.filters button{min-height:40px;padding:0 12px;border:1px solid var(--border-light);border-radius:999px;background:#fff}.filters button[aria-pressed=true]{border-color:var(--primary);background:var(--primary-50);color:var(--primary)}.table-wrapper{overflow-x:auto}.table{min-width:900px}.compact{min-width:110px}.negative{color:#b91c1c}.positive{color:#047857}.summary{margin-top:16px;padding:16px;border-radius:12px;background:#fffaf6}.summary h3{margin:0 0 10px;font-size:16px}.summary dl{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:0}.summary dl div{display:grid;gap:4px}.summary dt{color:var(--text-mid);font-size:12px}.summary dd{margin:0;font-size:18px;font-weight:800}.actions{justify-content:flex-end;margin-top:14px}.locked{color:var(--text-mid)}.count-page :is(button,input,select):focus-visible{outline:3px solid var(--primary);outline-offset:2px}.count-page :is(button,input,select){min-height:40px}@media(max-width:900px){.workspace{grid-template-columns:1fr}.table-wrapper{overflow:visible}.table thead{display:none}.table,.table tbody,.table tr,.table td{display:block;widt